// §9.1: the app command manifest puts every app command under the ACL (autogenerated
// `allow-<command-with-dashes>` permissions); `capabilities/main.json` grants exactly those.
include!("src/commands/names.rs");

fn main() {
    println!("cargo:rerun-if-changed=src/commands/names.rs");
    // The `e2e` feature (src/e2e.rs) redirects all user state for automated tests and
    // must never be in a release-profile build. `PROFILE` follows the profile's inheritance
    // (release vs dev), so overriding `debug-assertions` or `opt-level` cannot bypass this. The
    // `compile_error!` in src/e2e.rs stays as a second layer.
    if std::env::var_os("CARGO_FEATURE_E2E").is_some()
        && std::env::var("PROFILE").as_deref() == Ok("release")
    {
        panic!(
            "the `e2e` feature must never be built with a release profile; use \
             `tauri build --debug --features e2e`"
        );
    }
    let attributes = tauri_build::Attributes::new()
        .app_manifest(tauri_build::AppManifest::new().commands(COMMAND_NAMES));
    if let Err(error) = tauri_build::try_build(attributes) {
        panic!("tauri-build failed: {error:#}");
    }
}
